import{_ as o,o as i,c as a,a2 as t}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"ADR-0048 — Presentazioni Marp: editor a tutta larghezza, tab SlideShow, export nel ribbon e PPTX modificabile","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0048-presentazioni-marp-slideshow-ribbon-pptx.md","filePath":"adr/0048-presentazioni-marp-slideshow-ribbon-pptx.md"}'),n={name:"adr/0048-presentazioni-marp-slideshow-ribbon-pptx.md"};function d(r,e,l,c,s,p){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0048-—-presentazioni-marp-editor-a-tutta-larghezza-tab-slideshow-export-nel-ribbon-e-pptx-modificabile" tabindex="-1">ADR-0048 — Presentazioni Marp: editor a tutta larghezza, tab SlideShow, export nel ribbon e PPTX modificabile <a class="header-anchor" href="#adr-0048-—-presentazioni-marp-editor-a-tutta-larghezza-tab-slideshow-export-nel-ribbon-e-pptx-modificabile" aria-label="Permalink to &quot;ADR-0048 — Presentazioni Marp: editor a tutta larghezza, tab SlideShow, export nel ribbon e PPTX modificabile&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Data</strong></td><td>2026-11-05</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.2.1 (matrice funzioni), §2.3 (editor e rendering), §3.4.5 (strategia per tipo di file); V-02/D-01, D-04, V-07; ADR-0020, ADR-0027, ADR-0045, ADR-0047</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì, come ADR-0047: §2.2.1 (righe «Presentazioni Marp» e «Export»: vista, tab SlideShow, ribbon, PPTX), §3.4.5 (<code>.marp</code> nella riga «Markdown»), §3.4.6 (<code>.marp</code> nel contenuto sincronizzato) → richiede aggiornamento di <code>Specifications.md</code> da parte dell&#39;owner, che deve recepire insieme ADR-0047 e ADR-0048</td></tr><tr><td><strong>Superfici</strong></td><td>desktop (editor, tab SlideShow, ribbon, binding <code>ExportAPI.SaveFile</code>) · workbench web (stessa UI sul core WASM; il PPTX viene scaricato; prove sul core nella matrice <code>e2e:workbench-ui</code>) · console: nessuna · cloud: nessuna (il server non interpreta il contenuto)</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p><a href="./0047-apertura-file-per-tipo-e-presentazioni-marp.html">ADR-0047</a> (1.3.3) ha introdotto i file <code>.marp</code> con una vista divisa: editor a sinistra, anteprima delle slide a destra, pulsanti Presenta / HTML / PDF / PPTX (quest&#39;ultimo disabilitato). L&#39;uso ha mostrato tre problemi:</p><ul><li>la vista doppia occupa spazio e duplica ciò che i disegni già offrono nel tab <strong>SlideShow</strong> della sidebar destra (cornici, card, riordino, esclusione, note, presentazione a tutto schermo); per un <code>.marp</code> quel tab mostra invece «Apri una nota Markdown per presentarla»;</li><li>sul <code>.marp</code> compaiono i pulsanti Live / Sorgente / Lettura, che non hanno effetto: <code>.mode-toggle { display: flex }</code> annulla l&#39;attributo <code>hidden</code>;</li><li>gli export sono nella barra della vista, non nel ribbon dove stanno quelli di note e disegni, e il PPTX manca.</li></ul><p>Vincoli invariati rispetto ad ADR-0047: nessun CSS dell&#39;autore e HTML sanificato (V-02/D-01), offline, CSP con <code>frame-src &#39;none&#39;</code> e senza <code>unsafe-eval</code>, finestra singola (V-07), parità desktop/web per costruzione (ADR-0045), budget dei bundle (ADR-0020).</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><h3 id="_1-vista" tabindex="-1">1. Vista <a class="header-anchor" href="#_1-vista" aria-label="Permalink to &quot;1. Vista&quot;">​</a></h3><p>La vista divisa di ADR-0047 §4 è tolta. Un <code>.marp</code> si apre come una nota, con lo stesso ramo editor di <code>workspace/NoteView</code>, a tutta larghezza e con la modalità forzata a Source. I pulsanti Live / Sorgente / Lettura non compaiono per i <code>.marp</code>; il difetto CSS si corregge con <code>.mode-toggle[hidden] { display: none }</code>. L&#39;anteprima vive solo nel tab SlideShow e nella presentazione a tutto schermo. Restano <code>marp:new</code>, il flag <code>presentations</code> e le regole di rendering di ADR-0047 §3.</p><h3 id="_2-modello-delle-slide" tabindex="-1">2. Modello delle slide <a class="header-anchor" href="#_2-modello-delle-slide" aria-label="Permalink to &quot;2. Modello delle slide&quot;">​</a></h3><p>Un modulo puro (<code>marp/slides.ts</code>) ricava dal testo, per ogni slide: indice, righe di inizio e fine, titolo (primo heading, altrimenti la prima riga di testo), note e stato incluso/escluso. Le slide sono i blocchi tra i separatori <code>---</code> (frontmatter e blocchi di codice esclusi) o, con <code>headingDivider</code>, le sezioni per heading.</p><ul><li><strong>Escludere una slide</strong> aggiunge <code>&lt;!-- memobrain: hidden --&gt;</code> nel suo blocco; includerla lo toglie (idempotente). Il commento non è una direttiva di Marp, quindi per Marp è una nota: un client ≤ 1.3.3 e gli altri strumenti Marp mostrano comunque la slide e possono trattare il commento come nota del relatore. L&#39;esclusione vale quindi solo in MemoBrain Notes: è una scelta di compatibilità accettata.</li><li><strong>Note del relatore</strong>: i commenti HTML che non sono direttive di Marp, né il marcatore <code>memobrain: hidden</code>, né commenti di strumenti (<code>prettier-ignore</code>, <code>markdownlint-*</code>, <code>lint disable|enable|ignore</code>, che Marpit tiene fuori dalle note); la convenzione nativa di Marp. Più note nella stessa slide si uniscono, separate da una riga vuota.</li><li><strong>Che cosa è una direttiva</strong> (<code>DIRECTIVE_KEYS</code> in <code>marp/slides.ts</code>, che un test confronta con il motore): un commento che è una mappa YAML con almeno una chiave di direttiva. Le globali sono <code>theme</code>, <code>style</code>, <code>headingDivider</code>, <code>lang</code>, <code>size</code>, <code>math</code>; le locali <code>class</code>, <code>paginate</code>, <code>header</code>, <code>footer</code>, <code>backgroundColor</code>, <code>backgroundImage</code>, <code>backgroundPosition</code>, <code>backgroundRepeat</code>, <code>backgroundSize</code>, <code>color</code>, anche con il prefisso <code>_</code> (valgono per una sola slide). Vale anche la forma flow-YAML (<code>{theme: gaia}</code>). Chiavi come <code>title</code>, <code>author</code> o <code>transition</code> non sono direttive di Marp Core: per esso sono note.</li><li><strong>Una nota che sembrerebbe una direttiva</strong> (per esempio «theme: appunti») verrebbe letta da Marp come configurazione. Quando il pannello la scrive, la neutralizza (<code>neutralize</code>) inserendo un carattere invisibile U+200B dopo la chiave di direttiva; <code>displayNote</code> lo toglie, quindi non compare nel pannello, nella presentazione né nelle note del PPTX.</li><li><strong>Dove si cercano i commenti</strong>: non sono note, e non vengono mai toccati, i commenti dentro un code span, in un blocco di codice recintato o indentato. Una nota di una sola riga si riscrive sul posto. Una nota su più righe è sicura solo come blocco a colonna 0: se la nota esistente sta in una lista, in una citazione o in un paragrafo, viene tolta e la nuova è scritta come blocco in fondo alla slide.</li><li><strong>Frontmatter</strong>: le chiavi <code>memobrain-loop</code> (la presentazione riparte dopo l&#39;ultima slide) e <code>memobrain-notes</code> (note visibili in presentazione) sono ignorate da Marp; <code>paginate</code> e <code>theme</code> sono le direttive native (temi <code>default</code>, <code>gaia</code>, <code>uncover</code>).</li><li><strong>Riordino</strong>: scambia i blocchi sorgente tra i separatori <code>---</code>. Non è disponibile con <code>headingDivider</code>, perché le slide non hanno separatori: il pulsante resta disabilitato con un tooltip.</li><li>Ogni modifica (riordino, esclusione, note, frontmatter) è una transazione di CodeMirror su <code>getEditor(paneId)</code> (<code>marp/controller.ts</code>): si annulla con undo, non perde testo, ed è rifiutata se l&#39;editor è in sola lettura. Lo stato letto dal pannello (<code>marp/deckStore.ts</code>) segue l&#39;editor con 300 ms di attesa dopo la digitazione.</li><li><strong>Numeri di pagina</strong>: seguono il contatore di Marp (<code>paginate</code>, <code>_paginate: skip</code>, <code>hold</code>). Le slide escluse non lasciano buchi: <code>renumberPages</code> chiude lo scarto solo per le slide escluse che avevano fatto avanzare il contatore, e <code>includedDeck</code> applica lo stesso criterio alla presentazione e agli export.</li></ul><h3 id="_3-tab-slideshow-per-i-marp" tabindex="-1">3. Tab SlideShow per i <code>.marp</code> <a class="header-anchor" href="#_3-tab-slideshow-per-i-marp" aria-label="Permalink to &quot;3. Tab SlideShow per i `.marp`&quot;">​</a></h3><p><code>SlidesPanel</code> instrada i <code>.marp</code> a un pannello dedicato con le stesse funzioni di quello dei disegni:</p><ul><li>barra degli strumenti: presenta, stampa/PDF, informazioni (slide totali e incluse, tema, parole, note), impostazioni (loop, numeri di pagina, note in presentazione, tema), menu <code>…</code> (includi tutte, escludi tutte);</li><li>riepilogo «n di m incluse» e una card per slide: titolo, miniatura (Shadow DOM con il CSS del tema, solo la slide), vai alla slide nell&#39;editor, riordina, includi/escludi, presenta da qui;</li><li>click su una card: la seleziona, sposta il cursore e apre la casella delle note, salvate come commenti HTML; la card della slide sotto il cursore è evidenziata;</li><li>tutto disabilitato in sola lettura. <code>.excalidraw</code> e <code>.md</code> restano come oggi.</li></ul><h3 id="_4-presentazione-a-tutto-schermo" tabindex="-1">4. Presentazione a tutto schermo <a class="header-anchor" href="#_4-presentazione-a-tutto-schermo" aria-label="Permalink to &quot;4. Presentazione a tutto schermo&quot;">​</a></h3><p>Un overlay (come quello dei disegni, <code>util/fullscreen.ts</code>) mostra le slide incluse del testo corrente, comprese le modifiche non salvate, con gli stessi tasti e lo stesso loop dei disegni, la barra con slide precedente/successiva, selettore, «n / totale» e note se attive. Uscire dal tutto schermo chiude la presentazione. <code>marp:present</code> apre l&#39;overlay. Il pannello e la presentazione sono caricati in modo lazy (<code>lazyView</code>), per restare nel budget del bundle iniziale (ADR-0020).</p><h3 id="_5-export-nel-ribbon-per-tipo-di-file-attivo" tabindex="-1">5. Export nel ribbon, per tipo di file attivo <a class="header-anchor" href="#_5-export-nel-ribbon-per-tipo-di-file-attivo" aria-label="Permalink to &quot;5. Export nel ribbon, per tipo di file attivo&quot;">​</a></h3><p>Gli strumenti di creazione restano fissi; il gruppo export dipende dal tipo del file attivo:</p><table tabindex="0"><thead><tr><th>File attivo</th><th>Pulsanti</th></tr></thead><tbody><tr><td>nota</td><td><code>note:export-pdf</code>, <code>note:export-image</code>, <code>note:export-html</code></td></tr><tr><td>disegno</td><td><code>drawing:export-png</code>, <code>drawing:export-svg</code>, <code>drawing:export-pdf</code></td></tr><tr><td>presentazione</td><td><code>marp:export-html</code>, <code>marp:export-pdf</code>, <code>marp:export-pptx</code></td></tr><tr><td>altro</td><td>nessuno</td></tr></tbody></table><p><code>note:export-pdf</code> diventa attivo solo per le note <code>.md</code> (oggi lo è per qualsiasi file). I tre comandi dei disegni sono nuovi (feature <code>drawing.export</code>): PNG e SVG aprono la finestra di esportazione con il formato preselezionato, PDF stampa l&#39;intero disegno. I comandi dei disegni agiscono sul disegno della scheda attiva (<code>getSceneController(path?)</code> in <code>drawing/actions/active.ts</code>); se in primo piano c&#39;è una nota, ripiegano sull&#39;ultimo editor di disegni registrato. Per lo stesso motivo il rilascio di un file del vault su un disegno agisce su quel disegno (<code>dropVaultFile(path, at, drawingPath)</code>), anche se non è la scheda attiva. Le slide escluse sono saltate in tutti e tre gli export delle presentazioni.</p><h3 id="_6-pptx-modificabile" tabindex="-1">6. PPTX modificabile <a class="header-anchor" href="#_6-pptx-modificabile" aria-label="Permalink to &quot;6. PPTX modificabile&quot;">​</a></h3><ul><li>Libreria <code>pptxgenjs</code> (MIT) a versione esatta (4.0.1 al momento della proposta), caricata on demand in un chunk lazy insieme al modulo <code>marp/pptx.ts</code>, senza rete e senza <code>eval</code>, compatibile con la CSP di desktop e Web UI.</li><li>Pagina 16:9 (<code>LAYOUT_WIDE</code>); le slide escluse sono saltate e i numeri di pagina seguono Marp (<code>includedDeck</code>).</li><li><strong>Mappatura dei contenuti</strong> dall&#39;HTML sanificato di <code>renderDeck</code>, con le immagini di <code>exportAssets</code>: h1–h6 → titolo o testo grande; paragrafi con grassetto, corsivo, codice e link come run di testo; <code>ul</code>/<code>ol</code> annidati → elenchi con livelli; <code>table</code> → tabella; <code>pre code</code> → testo monospazio; <code>img</code> → immagine; <code>blockquote</code> → testo rientrato; sfondi <code>![bg]</code> → immagine di sfondo; note del relatore → note PPTX; numero di pagina se c&#39;è <code>paginate</code>.</li><li><strong>Immagini non convertibili</strong>: gli SVG sono disegnati in PNG su un canvas (nessun lato oltre 2000 px). Quelle che non si riesce a rasterizzare (per esempio SVG che il canvas rifiuta) sono saltate e segnalate all&#39;utente (<code>deckToPptx</code> restituisce <code>skipped</code>, messaggio <code>marp.pptxSkipped</code>); il resto del file è salvato.</li><li><strong>Tema approssimato</strong>: colori e font per <code>default</code>, <code>gaia</code> e <code>uncover</code>, e classi <code>invert</code> e <code>lead</code>. Il risultato non è identico all&#39;HTML: il testo è modificabile ma l&#39;aspetto è una resa vicina, non fedele.</li><li><strong>Salvataggio</strong>: <code>ExportAPI.SaveFile</code> accetta un nuovo MIME <code>application/vnd.openxmlformats-officedocument.presentationml.presentation</code> → <code>.pptx</code>. Il lato Go apre l&#39;archivio ZIP e richiede le voci <code>[Content_Types].xml</code> e <code>ppt/presentation.xml</code>; il limite <code>MaxBinaryBytes</code> non cambia. La firma dei binding non cambia. Nel workbench web il file è scaricato.</li><li><code>marp:export-pptx</code> si abilita con una presentazione aperta; la stringa «Non ancora disponibile» di ADR-0047 è tolta.</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>PPTX come immagini (una per slide)</strong> — scartata: il testo non sarebbe modificabile e, nel WebKit di macOS, il canvas viene bloccato (tainted) dagli SVG con <code>foreignObject</code>, quindi la rasterizzazione fallisce.</li><li><strong>Marp CLI</strong> — scartata: produce il PPTX con un Chromium headless, assente nella webview Wails e nel browser.</li><li><strong>Mantenere la vista divisa</strong> — scartata: duplica il tab SlideShow, occupa spazio e lascia l&#39;editor stretto.</li><li><strong>Escludere le slide con una chiave del frontmatter (elenco di indici)</strong> — scartata: fragile al riordino e ai merge a 3 vie; il commento nel blocco segue la slide.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Spec da aggiornare (owner), insieme ad ADR-0047: §2.2.1 (presentazioni, export per tipo di file, PPTX), §3.4.5 e §3.4.6 come da ADR-0047.</li><li>ADR-0047 è parzialmente superata da ADR-0048 per la vista divisa (§4) e il PPTX rinviato (§5 e relative alternative e conseguenze); il resto resta valido.</li><li>Compatibilità: il commento <code>&lt;!-- memobrain: hidden --&gt;</code> non è riconosciuto da client ≤ 1.3.3 né da altri strumenti Marp, che mostrano la slide e possono leggerlo come nota. Il merge a 3 vie dei <code>.marp</code> non cambia (sono ancora Markdown).</li><li>Nuova dipendenza (<code>pptxgenjs</code>) da tenere aggiornata, nel chunk lazy e dentro i budget dei bundle; la CSP non cambia.</li><li>La parità è registrata in <code>shared/parity/features.yaml</code> (voci <code>presentations</code> e <code>drawing.export</code>), con prove sul core WASM per il workbench.</li><li>Debito accettato: la resa del tema nel PPTX è approssimata; il riordino non è disponibile con <code>headingDivider</code>.</li></ul>',27)])])}const g=o(n,[["render",d]]);export{m as __pageData,g as default};
